"""engine.py - a tiny autograd engine (the Value class you built in Module 8).

Every Value remembers which Values made it and how, so calling .backward()
on a final result fills in .grad (the derivative) for every Value involved.
Inspired by Andrej Karpathy's micrograd (MIT licence).

Two extra "fused" helpers at the bottom, dot() and cross_entropy(), compute the
same results as chaining + * exp log, but as ONE node with a hand-written
backward rule. That makes training ~10x faster in pure Python. PyTorch does the
same thing with its built-in fused operations.
"""
import math


class Value:
    def __init__(self, data, _children=(), _op=""):
        self.data = data
        self.grad = 0.0
        self._backward = lambda: None
        self._prev = set(_children)
        self._op = _op

    def __repr__(self):
        return f"Value(data={self.data:.4f}, grad={self.grad:.4f})"

    def __add__(self, other):
        other = other if isinstance(other, Value) else Value(other)
        out = Value(self.data + other.data, (self, other), "+")

        def _backward():
            self.grad += out.grad
            other.grad += out.grad
        out._backward = _backward
        return out

    def __mul__(self, other):
        other = other if isinstance(other, Value) else Value(other)
        out = Value(self.data * other.data, (self, other), "*")

        def _backward():
            self.grad += other.data * out.grad
            other.grad += self.data * out.grad
        out._backward = _backward
        return out

    def __pow__(self, k):
        assert isinstance(k, (int, float)), "only number powers"
        out = Value(self.data ** k, (self,), f"**{k}")

        def _backward():
            self.grad += k * self.data ** (k - 1) * out.grad
        out._backward = _backward
        return out

    def tanh(self):
        t = math.tanh(self.data)
        out = Value(t, (self,), "tanh")

        def _backward():
            self.grad += (1 - t * t) * out.grad
        out._backward = _backward
        return out

    def exp(self):
        e = math.exp(self.data)
        out = Value(e, (self,), "exp")

        def _backward():
            self.grad += e * out.grad
        out._backward = _backward
        return out

    def log(self):
        out = Value(math.log(self.data), (self,), "log")

        def _backward():
            self.grad += (1.0 / self.data) * out.grad
        out._backward = _backward
        return out

    def relu(self):
        out = Value(self.data if self.data > 0 else 0.0, (self,), "relu")

        def _backward():
            self.grad += (1.0 if out.data > 0 else 0.0) * out.grad
        out._backward = _backward
        return out

    def backward(self):
        topo, visited = [], set()

        def build(v):
            if v not in visited:
                visited.add(v)
                for child in v._prev:
                    build(child)
                topo.append(v)
        build(self)
        self.grad = 1.0
        for v in reversed(topo):
            v._backward()

    # the rest are built from the operations above
    def __neg__(self):
        return self * -1

    def __sub__(self, other):
        return self + (-other)

    def __rsub__(self, other):
        return other + (-self)

    def __radd__(self, other):
        return self + other

    def __rmul__(self, other):
        return self * other

    def __truediv__(self, other):
        return self * other ** -1

    def __rtruediv__(self, other):
        return other * self ** -1


def dot(ws, xs, bias=None):
    """w1*x1 + w2*x2 + ... (+ bias) as a single Value node. xs may be Values or numbers."""
    xs = [x if isinstance(x, Value) else Value(x) for x in xs]
    total = sum(w.data * x.data for w, x in zip(ws, xs))
    children = list(ws) + xs
    if bias is not None:
        total += bias.data
        children.append(bias)
    out = Value(total, children, "dot")

    def _backward():
        g = out.grad
        for w, x in zip(ws, xs):
            w.grad += x.data * g
            x.grad += w.data * g
        if bias is not None:
            bias.grad += g
    out._backward = _backward
    return out


def cross_entropy(logits, target):
    """-log(softmax(logits)[target]) as a single Value node."""
    m = max(l.data for l in logits)
    exps = [math.exp(l.data - m) for l in logits]
    total = sum(exps)
    probs = [e / total for e in exps]
    out = Value(-math.log(probs[target]), logits, "xent")

    def _backward():
        g = out.grad
        for i, l in enumerate(logits):
            l.grad += (probs[i] - (1.0 if i == target else 0.0)) * g
    out._backward = _backward
    return out

