"""lmdata.py - helpers for loading the bundled corpus (Modules 9-10)."""


def load_text(path="corpus.txt"):
    """Read corpus.txt, lowercase it, keep only a-z and single spaces.
    That leaves a tiny 27-character vocabulary: ' ' plus 'a'..'z'."""
    with open(path, encoding="utf-8") as f:
        raw = f.read().lower()
    cleaned = "".join(ch if "a" <= ch <= "z" else " " for ch in raw)
    return " ".join(cleaned.split())


def build_vocab(text):
    chars = sorted(set(text))
    stoi = {ch: i for i, ch in enumerate(chars)}
    itos = {i: ch for ch, i in stoi.items()}
    return chars, stoi, itos

