"""Runs the learner's code, then the lesson's hidden test, inside a temp folder.
Writes the verdict to _result.json. (Copied next to your_code.py for each check.)"""
import contextlib
import io
import json
import math
import re
import sys
import traceback

USER_FILE = "your_code.py"


def user_traceback(exc):
    """Format an exception showing only frames from the learner's file."""
    if isinstance(exc, SyntaxError):
        return "".join(traceback.format_exception_only(type(exc), exc))
    tb = exc.__traceback__
    while tb is not None and tb.tb_frame.f_code.co_filename != USER_FILE:
        tb = tb.tb_next
    return "".join(traceback.format_exception(type(exc), exc, tb))


def run_user(src):
    """Execute source as the learner's program. Returns (namespace, printed_output)."""
    ns = {"__name__": "__main__", "__file__": USER_FILE}
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        exec(compile(src, USER_FILE, "exec"), ns)
    return ns, buf.getvalue()


def main():
    with open(USER_FILE, encoding="utf-8") as f:
        src = f.read()
    with open("_test.py", encoding="utf-8") as f:
        test = f.read()
    result = {"status": "fail", "message": "", "stdout": "", "stderr": ""}

    # 1) run the learner's code
    buf = io.StringIO()
    ns = {"__name__": "__main__", "__file__": USER_FILE}
    try:
        code = compile(src, USER_FILE, "exec")
        with contextlib.redirect_stdout(buf):
            exec(code, ns)
    except SystemExit:
        pass
    except BaseException as e:  # noqa
        result.update(status="error", stdout=buf.getvalue(), stderr=user_traceback(e),
                      message="Your code crashed before I could check it. Fix the error below first.")
        write(result)
        return
    out = buf.getvalue()
    result["stdout"] = out

    # 2) run the hidden test with the learner's variables/functions visible
    def with_var(name, value):
        """Re-run the learner's code with the last `name = ...` line replaced."""
        pat = re.compile(r"^(%s\s*=\s*).*$" % re.escape(name), re.M)
        if not pat.search(src):
            raise AssertionError(f"Keep the line `{name} = ...` in your code so I can try other values.")
        m = list(pat.finditer(src))[-1]  # last assignment wins, so replace that one
        new_src = src[:m.start()] + m.group(1) + repr(value) + src[m.end():]
        return run_user(new_src)

    def approx(a, b, tol=1e-6):
        # numbers, or lists/tuples of numbers (element by element)
        if isinstance(b, (list, tuple)):
            try:
                return len(a) == len(b) and all(approx(x, y, tol) for x, y in zip(a, b))
            except TypeError:
                return False
        try:
            return abs(a - b) <= tol * max(1.0, abs(b))
        except TypeError:
            return False

    def lines(text=None):
        return [ln.rstrip() for ln in (out if text is None else text).strip().splitlines()]

    tns = dict(ns)
    tns.update(OUT=out, SRC=src, with_var=with_var, run_user=run_user,
               approx=approx, lines=lines, math=math)
    try:
        tb_buf = io.StringIO()
        with contextlib.redirect_stdout(tb_buf):
            exec(compile(test, "_hidden_test.py", "exec"), tns)
        result["status"] = "pass"
        result["message"] = tns.get("PASS_MESSAGE", "All checks passed!")
    except AssertionError as e:
        msg = str(e) or "Not quite right yet. Compare your result with the task."
        # "@phrase|message": phrase is a quote from the task, so the app can say
        # "re-read the task line about <phrase>" and highlight that line.
        if msg.startswith("@") and "|" in msg:
            ref, msg = msg[1:].split("|", 1)
            result["task_ref"] = ref.strip()
        result["message"] = msg.strip()
    except NameError as e:
        m = re.search(r"name '(\w+)' is not defined", str(e))
        nm = m.group(1) if m else "something"
        result["message"] = (f"I couldn't find `{nm}`. Make sure you created it with exactly "
                             f"that name (spelling and capitals matter).")
    except BaseException as e:  # noqa
        result["message"] = ("Your code ran, but it raised an error while I was testing it:\n"
                             + "".join(traceback.format_exception_only(type(e), e)).strip())
        result["stderr"] = user_traceback(e) if _has_user_frame(e) else ""
    write(result)


def _has_user_frame(e):
    tb = e.__traceback__
    while tb is not None:
        if tb.tb_frame.f_code.co_filename == USER_FILE:
            return True
        tb = tb.tb_next
    return False


def write(result):
    with open("_result.json", "w", encoding="utf-8") as f:
        json.dump(result, f)


if __name__ == "__main__":
    sys.setrecursionlimit(10000)
    main()

