"""Built-in Socratic tutor: rule-based, offline, stdlib only.

It coaches with questions and nudges. It never hands out a full solution.
The last nudge of a finding may point at the exact line to change.

Used by the desktop app (/api/tutor) and, unchanged, by the phone coding page
(Pyodide loads this file from runtime.json).
"""
from __future__ import annotations

import ast
import io
import re
import sys
import time
import traceback
from contextlib import redirect_stdout

try:
    from errors import explain_error
except ImportError:
    from pylearn_errors import explain_error  # type: ignore

try:
    from lessons.tutor_notes import GENERAL, NOTES
except ImportError:
    try:
        from tutor_notes import GENERAL, NOTES  # type: ignore
    except ImportError:
        GENERAL, NOTES = {"mistakes": []}, {}

MAX_TRACE_STEPS = 80
MAX_TRACE_SECS = 2.0
MAX_TRACE_LINES = 40
MAX_RUN_SECS = 1.5
MUTATING = {"append", "extend", "sort", "reverse", "remove", "clear", "insert", "pop"}


def _notes(lesson):
    extra = (lesson or {}).get("tutor") or NOTES.get((lesson or {}).get("id") or "", {})
    return extra, GENERAL


def _note_for(lesson, rule):
    extra, general = _notes(lesson)
    for block in (extra.get("mistakes") or []), (general.get("mistakes") or []):
        for m in block:
            if m.get("id") == rule:
                return m
    return {}


def _task_focus(lesson):
    extra, _ = _notes(lesson)
    return extra.get("task_focus") or ""


def _lines(src):
    return (src or "").splitlines() or [""]


def _at(src, lineno):
    ls = _lines(src)
    if not lineno or not (1 <= lineno <= len(ls)):
        return ""
    return ls[lineno - 1]


def _clip(s, n=80):
    s = re.sub(r"\s+", " ", (s or "")).strip()
    return s if len(s) <= n else s[: n - 1] + "\u2026"


def _parse(src):
    try:
        return ast.parse(src or ""), None
    except SyntaxError as e:
        return None, e


def _walk_stmts(tree):
    """Yield (stmt, loop, block, fn) for every statement.

    loop: innermost For/While; block: innermost For/While/If; fn: enclosing FunctionDef.
    """
    if tree is None:
        return

    def go(stmts, loop, block, fn):
        for s in stmts:
            yield s, loop, block, fn
            loop2 = s if isinstance(s, (ast.For, ast.While)) else loop
            block2 = s if isinstance(s, (ast.For, ast.While, ast.If)) else block
            fn2 = s if isinstance(s, (ast.FunctionDef, ast.AsyncFunctionDef)) else fn
            for attr in ("body", "orelse", "finalbody"):
                if getattr(s, attr, None):
                    yield from go(getattr(s, attr), loop2, block2, fn2)
            if isinstance(s, ast.Try):
                for h in s.handlers:
                    yield from go(h.body, loop2, block2, fn2)

    yield from go(tree.body, None, None, None)


def _dump(node):
    try:
        return ast.unparse(node)
    except Exception:
        return ""


_MISSING = object()


def _const(node):
    """Return the value of an ast.Constant, or _MISSING (never None for non-constants)."""
    if isinstance(node, ast.Constant):
        return node.value
    return _MISSING


def _is_eq_compare(node):
    return isinstance(node, ast.Compare) and any(isinstance(op, ast.Eq) for op in node.ops)


def _calls_named(node, names):
    if not isinstance(node, ast.Call):
        return False
    f = node.func
    if isinstance(f, ast.Name):
        return f.id in names
    if isinstance(f, ast.Attribute):
        return f.attr in names
    return False

def _phrase_expr(node):
    """Plain-English reading of an expression, using the course phrasing."""
    if node is None:
        return "this"
    if isinstance(node, ast.Constant):
        return repr(node.value)
    if isinstance(node, ast.Name):
        return f"`{node.id}`"
    if isinstance(node, ast.Attribute):
        return f"{_phrase_expr(node.value)}.`{node.attr}`"
    if isinstance(node, ast.Subscript):
        return f"{_phrase_expr(node.value)} at position {_phrase_expr(node.slice)}"
    if isinstance(node, ast.Slice):
        a = _phrase_expr(node.lower) if node.lower else ""
        b = _phrase_expr(node.upper) if node.upper else ""
        if node.lower and node.upper:
            return f"{a} up to (but not including) {b}"
        if node.lower:
            return f"{a} to the end"
        if node.upper:
            return f"the start up to (but not including) {b}"
        return "a slice"
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Name) and node.func.id == "range":
            if len(node.args) == 1:
                return f"`range({_dump(node.args[0])})` (0, 1, \u2026, stopping before {_phrase_expr(node.args[0])})"
            if len(node.args) >= 2:
                return (f"`range({_dump(node.args[0])}, {_dump(node.args[1])})` "
                        f"(starting at {_phrase_expr(node.args[0])}, stopping before {_phrase_expr(node.args[1])})")
        if isinstance(node.func, ast.Attribute) and node.func.attr == "append":
            arg = _phrase_expr(node.args[0]) if node.args else "a value"
            return f"add {arg} to the end of the list {_phrase_expr(node.func.value)}"
        if isinstance(node.func, ast.Name) and node.func.id == "print":
            return "print " + ", ".join(_phrase_expr(a) for a in node.args) if node.args else "print a blank line"
        if isinstance(node.func, ast.Name) and node.func.id == "len":
            return f"the length of {_phrase_expr(node.args[0])}" if node.args else "a length"
        name = _dump(node.func)
        args = ", ".join(_phrase_expr(a) for a in node.args)
        return f"`{name}({_clip(args, 40)})`" if args else f"`{name}()`"
    if isinstance(node, ast.JoinedStr):
        names = [v.value.id for v in node.values
                 if isinstance(v, ast.FormattedValue) and isinstance(v.value, ast.Name)]
        if names:
            return "a line of text filling in " + ", ".join(f"`{n}`" for n in names)
        return "a line of text with values filled in"
    if isinstance(node, ast.FormattedValue):
        return _phrase_expr(node.value)
    if isinstance(node, ast.BinOp):
        a, b = _phrase_expr(node.left), _phrase_expr(node.right)
        if isinstance(node.op, ast.Mod):
            return f"the remainder when {a} is packed into groups of {b}"
        if isinstance(node.op, ast.Add):
            return f"{a} plus {b}"
        if isinstance(node.op, ast.Sub):
            return f"{a} minus {b}"
        if isinstance(node.op, ast.Mult):
            return f"{a} times {b}"
        if isinstance(node.op, ast.Div):
            return f"{a} divided by {b}"
        if isinstance(node.op, ast.FloorDiv):
            return f"how many whole times {b} fits into {a}"
        return f"{a} (combined with) {b}"
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
        return f"not ({_phrase_expr(node.operand)})"
    if isinstance(node, ast.BoolOp):
        op = " and " if isinstance(node.op, ast.And) else " or "
        return op.join(_phrase_expr(v) for v in node.values)
    if isinstance(node, ast.Compare):
        left = _phrase_expr(node.left)
        parts = []
        for op, comp in zip(node.ops, node.comparators):
            r = _phrase_expr(comp)
            if isinstance(op, ast.Eq):
                parts.append(f"is {left} equal to {r}?")
            elif isinstance(op, ast.NotEq):
                parts.append(f"is {left} not equal to {r}?")
            elif isinstance(op, ast.In):
                parts.append(f"is {left} found inside {r}?")
            elif isinstance(op, ast.NotIn):
                parts.append(f"is {left} not found inside {r}?")
            elif isinstance(op, ast.Lt):
                parts.append(f"is {left} less than {r}?")
            elif isinstance(op, ast.LtE):
                parts.append(f"is {left} less than or equal to {r}?")
            elif isinstance(op, ast.Gt):
                parts.append(f"is {left} greater than {r}?")
            elif isinstance(op, ast.GtE):
                parts.append(f"is {left} greater than or equal to {r}?")
            elif isinstance(op, ast.Is):
                parts.append(f"is {left} the same object as {r}?")
            else:
                parts.append(f"{left} compared with {r}")
            left = r
        return " and ".join(parts) if len(parts) > 1 else (parts[0] if parts else _dump(node))
    if isinstance(node, ast.List):
        return "a list: [" + ", ".join(_phrase_expr(x) for x in node.elts) + "]"
    if isinstance(node, ast.Tuple):
        return "a tuple (" + ", ".join(_phrase_expr(x) for x in node.elts) + ")"
    if isinstance(node, ast.Dict):
        return "a dictionary"
    if isinstance(node, ast.ListComp) and node.generators:
        g = node.generators[0]
        return f"a list built by taking each {_phrase_expr(g.target)} from {_phrase_expr(g.iter)}"
    return f"`{_clip(_dump(node))}`" if _dump(node) else "this"


def _explain_stmt(stmt):
    if isinstance(stmt, ast.Assign):
        tgt = ", ".join(_phrase_expr(t) for t in stmt.targets)
        if (isinstance(stmt.value, ast.Call) and isinstance(stmt.value.func, ast.Attribute)
                and stmt.value.func.attr in MUTATING):
            return (f"{tgt} gets value {_phrase_expr(stmt.value)}. Careful: "
                    f"`.{stmt.value.func.attr}(...)` changes the list in place and hands back `None`.")
        return f"{tgt} gets value {_phrase_expr(stmt.value)}."
    if isinstance(stmt, ast.AugAssign):
        name, val = _phrase_expr(stmt.target), _phrase_expr(stmt.value)
        if isinstance(stmt.op, ast.Add):
            return f"Add {val} to {name} and store it back in {name}."
        if isinstance(stmt.op, ast.Sub):
            return f"Subtract {val} from {name} and store it back in {name}."
        return f"Update {name} with {val}."
    if isinstance(stmt, ast.AnnAssign) and stmt.value is not None:
        return f"{_phrase_expr(stmt.target)} gets value {_phrase_expr(stmt.value)}."
    if isinstance(stmt, ast.Expr):
        v = stmt.value
        if _is_eq_compare(v):
            return (_phrase_expr(v).rstrip("?") + "? This line asks a question and then throws the answer away. "
                    "It does not store a value. To store, you would use a single `=`.")
        if isinstance(v, ast.Call) and isinstance(v.func, ast.Name) and v.func.id == "print":
            return "Print " + ", ".join(_phrase_expr(a) for a in v.args) + "." if v.args else "Print a blank line."
        if isinstance(v, ast.Call):
            return _phrase_expr(v).rstrip(".") + "."
        if isinstance(v, ast.Constant) and v.value is Ellipsis:
            return "This `...` is a placeholder. Replace it with your line."
        return _phrase_expr(v).rstrip(".") + "."
    if isinstance(stmt, ast.If):
        return "If this is True, run the indented lines: " + _phrase_expr(stmt.test)
    if isinstance(stmt, ast.For):
        return f"For each {_phrase_expr(stmt.target)} taken from {_phrase_expr(stmt.iter)}, run the indented lines."
    if isinstance(stmt, ast.While):
        return "While this is True, run the indented lines: " + _phrase_expr(stmt.test)
    if isinstance(stmt, ast.Break):
        return "Leave the loop immediately (`break`)."
    if isinstance(stmt, ast.Continue):
        return "Skip the rest of this round of the loop and go to the next item (`continue`)."
    if isinstance(stmt, ast.Return):
        if stmt.value is None:
            return "Leave the function and hand back `None`."
        return f"Leave the function and hand back {_phrase_expr(stmt.value)}."
    if isinstance(stmt, ast.Pass):
        return "`pass` does nothing. It is a placeholder for a block you have not written yet."
    if isinstance(stmt, ast.FunctionDef):
        args = ", ".join(a.arg for a in stmt.args.args)
        return f"Define a function `{stmt.name}`" + (f" that takes {args}." if args else ".")
    if isinstance(stmt, ast.Import):
        return "Bring in a module: " + ", ".join(a.name for a in stmt.names) + "."
    if isinstance(stmt, ast.ImportFrom):
        return f"Bring in names from `{stmt.module}`."
    if isinstance(stmt, ast.Assert):
        return "Check that this is True, otherwise stop: " + _phrase_expr(stmt.test)
    if isinstance(stmt, ast.Raise):
        return "Stop and raise an error."
    return None


def explain_line(src, lineno=None, lesson=None):
    """Plain English for one line (1-based). `src` may be a whole program or a single line."""
    text = src or ""
    if lineno is None and "\n" not in text:
        line, lineno, full = text, 1, text
    else:
        ls = _lines(text)
        n = lineno or 1
        if not (1 <= n <= len(ls)):
            return {"line": n, "text": "", "explain": "There is no such line in the current code."}
        line = ls[n - 1]
    raw = line
    s = line.strip()
    if not s:
        return {"line": lineno or 1, "text": raw, "explain": "This line is blank."}
    if s.startswith("#"):
        return {"line": lineno or 1, "text": raw,
                "explain": "This line is a comment. Python ignores it; it is a note for you."}
    tree, err = _parse(s)
    if err and s.endswith(":"):
        tree, err = _parse(s + "\n    pass")
    if tree and tree.body:
        stmt = tree.body[0]
        if s.startswith("elif "):
            msg = "Otherwise, if this is True, run the indented lines: " + _phrase_expr(stmt.test)
        elif s.startswith("else"):
            msg = "If none of the checks above were True, run the indented lines."
        else:
            msg = _explain_stmt(stmt)
        if msg:
            return {"line": lineno or 1, "text": raw, "explain": msg}
    return {"line": lineno or 1, "text": raw, "explain": _explain_unparsed(s)}


def _explain_unparsed(s):
    if re.search(r"[^=!<>]=[^=]", s) and s.strip().endswith(":") and re.search(r"\b(if|elif|while)\b", s):
        return ("This looks like a `=` (store) inside a condition. The test after `if`/`elif`/`while` "
                "has to be a question: use `==` to ask \"is \u2026 equal to \u2026?\".")
    m = re.match(r"^([A-Za-z_]\w*)\s*==\s*(.+)$", s)
    if m:
        return (f"Is `{m.group(1)}` equal to `{m.group(2).rstrip()}`? "
                "This line asks a question and does not store a value.")
    m = re.match(r"^([A-Za-z_]\w*)\s*=\s*(.+)$", s)
    if m:
        return f"`{m.group(1)}` gets value `{m.group(2).rstrip()}`."
    if s.startswith("for ") and " in " in s:
        return "For each item taken from a collection, run the indented lines."
    if "%" in s and "==" in s:
        return "This asks whether the remainder is equal to something (often 0, meaning it divides evenly)."
    return (f"This line is `{_clip(s, 60)}`. If it is not valid Python yet, finish the line "
            "(a missing colon `:` or a closing quote is a common cause) and ask again.")

def _safe_to_exec(lesson, src):
    if lesson and int(lesson.get("timeout") or 10) > 10:
        return False
    blob = (src or "") + "\n" + ((lesson or {}).get("solution") or "")
    if re.search(r"\b(engine|nn|lmdata)\b", blob):
        return False
    if len(_lines(src or "")) > 80:
        return False
    return True


def _exec(src, timeout=MAX_RUN_SECS):
    """Run source; return {stdout, stderr, ok, names}."""
    out, ns = io.StringIO(), {"__name__": "__main__"}
    t0 = time.time()

    def tracer(frame, event, arg):
        if time.time() - t0 > timeout:
            raise TimeoutError("stopped")
        return tracer if frame.f_code.co_filename == "<tutor>" else None

    try:
        tree = ast.parse(src)
        sys.settrace(tracer)
        try:
            with redirect_stdout(out):
                exec(compile(tree, "<tutor>", "exec"), ns)
        finally:
            sys.settrace(None)
        return {"stdout": out.getvalue(), "stderr": "", "ok": True,
                "names": {k: v for k, v in ns.items() if not k.startswith("_")}}
    except TimeoutError:
        sys.settrace(None)
        return {"stdout": out.getvalue(), "stderr": "TimeoutError", "ok": False, "names": {}, "timeout": True}
    except SyntaxError as e:
        sys.settrace(None)
        return {"stdout": "", "stderr": "".join(traceback.format_exception_only(type(e), e)),
                "ok": False, "names": {}, "syntax": e}
    except BaseException as e:  # noqa
        sys.settrace(None)
        tb = "".join(traceback.format_exception(type(e), e, e.__traceback__))
        return {"stdout": out.getvalue(), "stderr": "".join(traceback.format_exception_only(type(e), e)),
                "ok": False, "names": ns, "exc": type(e).__name__, "tb": tb}


def char_diff(got, want):
    """A small, visual, character-by-character comparison of two strings."""
    got = got if got is not None else ""
    want = want if want is not None else ""
    g, w = got.replace("\r\n", "\n"), want.replace("\r\n", "\n")
    if g.endswith("\n") and not w.endswith("\n"):
        g = g[:-1]
    if w.endswith("\n") and not g.endswith("\n"):
        w = w[:-1]
    n = min(len(g), len(w))
    i = 0
    while i < n and g[i] == w[i]:
        i += 1

    def vis(ch):
        return {" ": "\u00b7", "\t": "\u2192", "\n": "\u21b5"}.get(ch, ch)

    def mark(s, at):
        at = min(max(at, 0), len(s))
        if "\n" in s:
            line_start = s[:at].rfind("\n") + 1 if "\n" in s[:at] else 0
            line_end = s.find("\n", at)
            if line_end < 0:
                line_end = len(s)
            piece, col = s[line_start:line_end], at - line_start
        else:
            piece, col = s, at
        return "".join(vis(c) for c in piece), (" " * col + "\u25b2"), col

    g_show, g_caret, _ = mark(g, i)
    w_show, w_caret, _ = mark(w, i)
    same = g == w
    if same:
        kind, why = "same", "The two texts match exactly."
    elif i == len(g) < len(w):
        kind, why = "missing", f"The expected text continues after yours: it still wanted {len(w) - len(g)} more character(s)."
    elif i == len(w) < len(g):
        extra = g[i:]
        if extra and all(ch == " " for ch in extra):
            kind, why = "extra-space", "There is an extra space here." if len(extra)==1 else f"There are {len(extra)} extra spaces here."
        else:
            kind, why = "extra", f"Yours is longer: it has {len(g) - len(w)} extra character(s) at the end."
    elif i < len(g) and g[i] == " " and (i >= len(w) or w[i] != " "):
        kind, why = "extra-space", "There is an extra space here."
    elif i < len(w) and w[i] == " " and (i >= len(g) or g[i] != " "):
        kind, why = "missing-space", "A space is missing here."
    elif i < len(g) and i < len(w) and g[i].lower() == w[i].lower():
        kind, why = "case", f"The letter is the same but the capitalisation differs: yours has {vis(g[i])}, the task has {vis(w[i])}."
    elif i < len(g) and i < len(w) and (not g[i].isalnum() or not w[i].isalnum()):
        kind, why = "punct", f"The punctuation (or symbol) differs: yours has {vis(g[i])}, the task has {vis(w[i])}."
    elif i < len(g) and i < len(w):
        kind, why = "char", f"The characters differ here: yours has {vis(g[i])}, the task has {vis(w[i])}."
    else:
        kind, why = "char", "The two texts differ."
    caret = w_caret if kind.startswith("missing") or kind in ("case", "punct", "char", "same") else g_caret
    return {"got": got, "want": want, "at": i, "same": same, "kind": kind, "why": why,
            "got_shown": g_show, "want_shown": w_show, "caret": caret}


def _fmt_diff(d):
    if not d or d.get("same"):
        return ""
    return (f"yours:  {d['got_shown']}\n"
            f"want:   {d['want_shown']}\n"
            f"        {d['caret']}\n"
            f"{d['why']}")


def _joined_parts(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return [node.value]
    if isinstance(node, ast.JoinedStr):
        return [v.value for v in node.values if isinstance(v, ast.Constant)]
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        return _joined_parts(node.left) + _joined_parts(node.right)
    return []


def _print_shapes(tree):
    out = []
    if not tree:
        return out
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "print":
            parts = []
            for a in node.args:
                parts.extend(_joined_parts(a))
            out.append((getattr(node, "lineno", None), parts, _dump(node)))
    return out


def _expected_snippets(lesson):
    task = (lesson or {}).get("task") or ""
    bits = []
    for m in re.finditer(r"`([^`]+)`", task):
        s = m.group(1)
        if any(ch in s for ch in (" -> ", "/", ":", " ")) and " = " not in s and not s.startswith(
                ("print", "for ", "if ", "range", "word.", "ch ")):
            bits.append(s)
    for m in re.finditer(r"exactly `([^`]+)`", task):
        bits.append(m.group(1))
    return bits


def _finding(rule, priority, levels, line=None, task_ref="", diff=None):
    clean = []
    for lv in levels:
        if isinstance(lv, str):
            lv = {"question": lv}
        q = (lv.get("question") or "").strip()
        if q:
            clean.append({"question": q, "note": (lv.get("note") or "").strip(),
                          "show_line": bool(lv.get("show_line")),
                          "fix_hint": (lv.get("fix_hint") or "").strip()})
    if not clean:
        return None
    return {"rule": rule, "priority": priority, "levels": clean,
            "line": line, "task_ref": task_ref or "", "diff": diff}


def _levels_from_note(lesson, rule, fallback, line=None, last=None):
    note = _note_for(lesson, rule)
    qs = list(note.get("questions") or []) or list(fallback)
    levels = [{"question": q} for q in qs]
    if last:
        levels.append(last if isinstance(last, dict) else {"question": last, "show_line": True})
    elif line:
        levels.append({"question": "Look at this exact line. What is it doing, in your own words? Compare it with what the task asked for.",
                       "show_line": True})
    return levels, note.get("task_ref") or _task_focus(lesson) or ""

def detect_syntax(lesson, src, err):
    if not err:
        return None
    msg, line = err.msg or "", err.lineno or 1
    text = _at(src, line) or _at(src, (err.lineno or 1) - 1)
    if "Maybe you meant '=='" in (msg or "") or "cannot assign" in (msg or "") or (
        re.search(r"\b(if|elif|while)\b", text) and re.search(r"[^=!<>]=[^=]", text)
    ):
        levels, ref = _levels_from_note(lesson, "assign-in-cond", [
            "Python stopped on a `=` inside a condition. What kind of line is this \u2014 a store, or a yes/no question?",
            "After `if`, `elif` or `while`, Python needs a question. Which operator asks \"is this equal to that?\"",
        ], line, last={"question": "This is the line Python could not parse. The `=` here stores a value; a condition needs `==`.",
                       "show_line": True, "fix_hint": "In a condition, use `==` to compare. Keep a single `=` for storing."})
        return _finding("assign-in-cond", 10, levels, line, ref)
    expl = explain_error(f'File "your_code.py", line {line}\n{type(err).__name__}: {msg}\n', False, 10)
    levels = [
        {"question": "Python could not read this file's grammar, so nothing ran. Looking at the line it pointed at (or the one just above), what might be missing \u2014 a colon `:`, a closing quote, a bracket?"},
        {"question": (expl or "Read the last line of the error: it names the problem.") + " What will you change first?",
         "show_line": True},
    ]
    return _finding("syntax", 15, levels, line, _task_focus(lesson))


def detect_eq_as_assign(lesson, tree, src):
    hits = []
    for stmt, _loop, _block, _fn in _walk_stmts(tree):
        if isinstance(stmt, ast.Expr) and _is_eq_compare(stmt.value):
            hits.append(stmt)
    if not hits:
        return None
    line = hits[0].lineno
    more = " Several of your lines do this." if len(hits) > 1 else ""
    levels, ref = _levels_from_note(lesson, "eq-as-assign", [
        "You have a line that uses `==`. Read it out loud as \"is \u2026 equal to \u2026?\". Were you trying to *ask a question*, or to *store a value*?",
        "A comparison asks a question and then throws the True/False answer away, so the variable on the left never changes. Which line was meant to *give* a variable its value?",
    ], line, last={"question": f"This is the first line that asks a question instead of storing.{more} A single `=` on this line would store the value.",
                   "show_line": True,
                   "fix_hint": "On this line, `==` asks a question. A single `=` stores."})
    return _finding("eq-as-assign", 20, levels, line, ref)


def detect_no_call(lesson, tree, src):
    hits = []

    def check(test, lineno):
        if isinstance(test, ast.Attribute):
            hits.append((lineno, getattr(test, "attr", "")))
        elif isinstance(test, ast.BoolOp):
            for v in test.values:
                check(v, lineno)
        elif isinstance(test, ast.UnaryOp):
            check(test.operand, lineno)

    for stmt, _loop, _block, _fn in _walk_stmts(tree):
        if isinstance(stmt, (ast.If, ast.While)):
            check(stmt.test, stmt.lineno)
    if not hits:
        return None
    line, meth = hits[0][0], hits[0][1] or "isdigit"
    levels, ref = _levels_from_note(lesson, "no-call", [
        f"On one of your tests you mention `.{meth}` but you do not call it. What is the difference between `word.{meth}` and `word.{meth}()`?",
        "Without the parentheses, Python gives you the method itself (which is always considered True in an `if`). To *ask* the method a question, you have to call it.",
    ], line, last={"question": f"This is the test. Add `()` after `.{meth}` so the method actually runs.",
                   "show_line": True,
                   "fix_hint": f"Call the method: `.{meth}()` \u2014 the parentheses are what make it run."})
    return _finding("no-call", 25, levels, line, ref)


def detect_append_none(lesson, tree, src):
    hits = []
    for stmt, _loop, _block, _fn in _walk_stmts(tree):
        if isinstance(stmt, ast.Assign) and isinstance(stmt.value, ast.Call):
            f = stmt.value.func
            if isinstance(f, ast.Attribute) and f.attr in MUTATING:
                hits.append(stmt)
    if not hits:
        return None
    line, attr = hits[0].lineno, hits[0].value.func.attr
    levels, ref = _levels_from_note(lesson, "append-none", [
        f"`.{attr}(...)` changes a list in place. What does that method *hand back* as its result?",
        "If you write `lst = lst.append(x)`, `lst` becomes whatever `.append` returned. What is that value \u2014 and what happens to the list you meant to keep?",
    ], line, last={"question": f"This line saves the result of `.{attr}(...)`. That result is `None`. Call `.{attr}(...)` on its own line instead of assigning it.",
                   "show_line": True,
                   "fix_hint": "Use `logged.append(step)` as a statement. Do not assign the result."})
    return _finding("append-none", 30, levels, line, ref)


def detect_placeholder(lesson, tree, src):
    starter = (lesson or {}).get("starter") or ""
    body = src or ""
    if body.strip() == starter.strip() and starter.strip():
        levels, ref = _levels_from_note(lesson, "placeholder", [
            "The editor still has the starter sketch. Which comment or `None` is marking the place where your code should go?",
            "Read the task once more, then replace just the placeholder \u2014 you can keep the given variables.",
        ], None)
        return _finding("placeholder", 35, levels, None, ref)
    hits = []
    if tree:
        for node in ast.walk(tree):
            if isinstance(node, ast.Constant) and node.value is Ellipsis:
                hits.append(("ellipsis", node.lineno))
        starter_tree, _ = _parse(starter)
        starter_none = set()
        if starter_tree:
            for s, _loop, _block, _fn in _walk_stmts(starter_tree):
                if isinstance(s, ast.Assign) and _const(s.value) is None:
                    for t in s.targets:
                        if isinstance(t, ast.Name):
                            starter_none.add(t.id)
        later = {n: [] for n in starter_none}
        for s, _loop, _block, _fn in _walk_stmts(tree):
            if isinstance(s, ast.Assign):
                for t in s.targets:
                    if isinstance(t, ast.Name) and t.id in later:
                        later[t.id].append((s.lineno, _const(s.value)))
        for name, assigns in later.items():
            if assigns and all(v is None for _, v in assigns):
                hits.append(("none", assigns[0][0], name))
    if "..." in body and not any(h[0] == "ellipsis" for h in hits):
        for i, ln in enumerate(_lines(body), 1):
            if re.search(r"(^|\s)\.\.\.(\s|$)", ln) and not ln.strip().startswith("#"):
                hits.append(("ellipsis", i))
                break
    if not hits:
        return None
    kind, line = hits[0][0], hits[0][1]
    name = hits[0][2] if kind == "none" and len(hits[0]) > 2 else "it"
    if kind == "ellipsis":
        fallback = ["There is still a `...` in your code. That is a placeholder Python does not treat as working code. Which line is it on, and what should that line *do*?"]
        last = {"question": "This is the placeholder line. Replace `...` with the statement the comment (or the task) is asking for.",
                "show_line": True}
    else:
        fallback = [
            f"The starter set `{name} = None` as a sketch. Has any branch actually given `{name}` a real value?",
            f"If `{name}` is still `None` at the end, a later `print` will show `None`. Which line was meant to store its value?",
        ]
        last = {"question": f"`{name}` is still set to `None` and never changed. The line that *gives* it a value should use a single `=`.",
                "show_line": True,
                "fix_hint": f"Give `{name}` a value with `=` in each branch (not `==`, and not leaving it as `None`)."}
    levels, ref = _levels_from_note(lesson, "placeholder", fallback, line, last=last)
    return _finding("placeholder", 36, levels, line, ref)


def detect_print_vs_return(lesson, tree, src):
    sol_tree, _ = _parse((lesson or {}).get("solution") or "")
    if not tree or not sol_tree:
        return None

    def fns(t):
        return {n.name: n for n in ast.walk(t) if isinstance(n, ast.FunctionDef)}

    user_f, sol_f = fns(tree), fns(sol_tree)
    for name, sn in sol_f.items():
        un = user_f.get(name)
        if not un:
            continue
        sol_returns = any(isinstance(x, ast.Return) and x.value is not None for x in ast.walk(sn))
        user_returns = any(isinstance(x, ast.Return) and x.value is not None for x in ast.walk(un))
        user_prints = any(isinstance(x, ast.Call) and _calls_named(x, {"print"}) for x in ast.walk(un))
        sol_prints = any(isinstance(x, ast.Call) and _calls_named(x, {"print"}) for x in ast.walk(sn))
        if sol_returns and user_prints and not user_returns:
            levels, ref = _levels_from_note(lesson, "print-vs-return", [
                f"The task asks `{name}` to *hand a value back* to the caller. `print` shows a value on the screen, but the caller does not receive it. What is the keyword that hands a value back?",
                "If a function finishes without `return`, the caller gets `None`. Where should the value be returned from?",
            ], un.lineno, last={"question": f"Inside `{name}`, you print a value but never `return` it. Use `return` so the caller receives the value.",
                               "show_line": True,
                               "fix_hint": "Use `return ...` so the caller receives the value. `print` only shows it."})
            return _finding("print-vs-return", 40, levels, un.lineno, ref)
        if sol_prints and user_returns and not user_prints and not sol_returns:
            levels, ref = _levels_from_note(lesson, "print-vs-return", [
                f"The task wants `{name}` to *show* a value (print it). `return` hands it back quietly, with nothing appearing on the screen. Which one did the task ask for?",
            ], un.lineno, last={"question": f"Inside `{name}`, you `return` a value but the task asked you to print it.",
                               "show_line": True,
                               "fix_hint": "Use `print(...)` when the task asks for output on the screen."})
            return _finding("print-vs-return", 40, levels, un.lineno, ref)
    for s, _loop, _block, fn in _walk_stmts(tree):
        if isinstance(s, ast.Return) and fn is None:
            levels, ref = _levels_from_note(lesson, "print-vs-return", [
                "`return` only works inside a function. At the top level, what do you use to *show* a value?",
            ], s.lineno, last={"question": "This `return` sits outside any function. Use `print(...)` here, or move it inside a `def`.",
                               "show_line": True})
            return _finding("print-vs-return", 40, levels, s.lineno, ref)
    return None

def _list_is_empty_literal(node):
    return (isinstance(node, ast.List) and not node.elts) or (isinstance(node, ast.Dict) and not node.keys)


def detect_accumulator(lesson, tree, src):
    if not tree:
        return None
    for stmt, loop, block, _fn in _walk_stmts(tree):
        if not isinstance(loop, (ast.For, ast.While)):
            continue
        if not isinstance(stmt, ast.Assign):
            continue
        empty = _const(stmt.value) in (0, 0.0, "", None) or _list_is_empty_literal(stmt.value)
        if not empty:
            continue
        names = [t.id for t in stmt.targets if isinstance(t, ast.Name)]
        used = set()
        for s2, _loop, _block, _fn in _walk_stmts(ast.Module(body=loop.body, type_ignores=[])):
            if isinstance(s2, ast.AugAssign) and isinstance(s2.target, ast.Name) and s2.target.id in names:
                used.add(s2.target.id)
            if isinstance(s2, ast.Expr) and isinstance(s2.value, ast.Call) and isinstance(s2.value.func, ast.Attribute):
                if (isinstance(s2.value.func.value, ast.Name) and s2.value.func.value.id in names
                        and s2.value.func.attr in MUTATING):
                    used.add(s2.value.func.value.id)
        hit = next((n for n in names if n in used), None)
        if hit:
            levels, ref = _levels_from_note(lesson, "accumulator", [
                f"You change `{hit}` inside the loop (you add to it or append). Look at where `{hit}` is set to {_dump(stmt.value) or 'its starting value'}. Is that line indented *under* the `for`/`while`, or does it sit *before* the loop?",
                f"If `{hit}` is reset every time around, it never builds up. Where should the starting value be set so it happens only once?",
            ], stmt.lineno, last={"question": f"This line resets `{hit}` on every pass of the loop. Move the starting value to just *above* the loop, at the same indent as `for`/`while`.",
                                  "show_line": True,
                                  "fix_hint": f"Set `{hit}` to its starting value once, before the loop, then update it inside."})
            return _finding("accumulator", 45, levels, stmt.lineno, ref)

    def scan(stmts, seen):
        cur = set(seen)
        for s in stmts:
            if isinstance(s, ast.Assign):
                for t in s.targets:
                    if isinstance(t, ast.Name):
                        cur.add(t.id)
            if isinstance(s, ast.AugAssign) and isinstance(s.target, ast.Name) and s.target.id not in cur:
                return s
            if isinstance(s, (ast.For, ast.While, ast.If, ast.With, ast.Try)):
                for attr in ("body", "orelse", "finalbody"):
                    if getattr(s, attr, None):
                        f = scan(getattr(s, attr), cur)
                        if f:
                            return f
                if isinstance(s, ast.Try):
                    for h in s.handlers:
                        f = scan(h.body, cur)
                        if f:
                            return f
            if isinstance(s, ast.FunctionDef):
                f = scan(s.body, {a.arg for a in s.args.args})
                if f:
                    return f
        return None

    hit = scan(tree.body, set())
    if hit:
        name, line = hit.target.id, hit.lineno
        levels, ref = _levels_from_note(lesson, "accumulator", [
            f"You update `{name}` with `+=` (or similar), but I cannot see where `{name}` first gets a starting value. What should it be *before* the loop starts \u2014 0, or `[]`?",
        ], line, last={"question": f"Give `{name}` a starting value on a line *above* the loop, then keep this update inside the loop.",
                       "show_line": True,
                       "fix_hint": f"Before the loop: `{name} = 0` (or `{name} = []` if you are collecting). Then update it inside."})
        return _finding("accumulator", 46, levels, line, ref)
    return None


def detect_elif_order(lesson, tree, src):
    if not tree:
        return None

    def chain(stmt):
        tests = []
        while isinstance(stmt, ast.If):
            tests.append((stmt.lineno, stmt.test))
            if len(stmt.orelse) == 1 and isinstance(stmt.orelse[0], ast.If):
                stmt = stmt.orelse[0]
            else:
                break
        return tests

    seen = set()
    for stmt, _loop, _block, _fn in _walk_stmts(tree):
        if not isinstance(stmt, ast.If) or id(stmt) in seen:
            continue
        tests = chain(stmt)
        for ln, test in tests:
            seen.add(id(stmt))
        earlier_sub = {}

        def is_empty_check(test):
            if isinstance(test, ast.Compare) and any(isinstance(op, ast.Eq) for op in test.ops):
                if isinstance(test.left, ast.Name) and any(_const(c) == "" for c in test.comparators):
                    return test.left.id
            return None

        for ln, test in tests:
            for n in ast.walk(test):
                if isinstance(n, ast.Subscript) and isinstance(n.value, ast.Name):
                    earlier_sub.setdefault(n.value.id, ln)
                if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Subscript) and isinstance(n.value.value, ast.Name):
                    earlier_sub.setdefault(n.value.value.id, ln)
            name = is_empty_check(test)
            if name and name in earlier_sub and earlier_sub[name] < ln:
                levels, ref = _levels_from_note(lesson, "elif-order", [
                    f"You look at `{name}[0]` (or something on the first character) *before* you check whether `{name}` is empty. What happens if `{name}` is `\"\"`?",
                    "Python stops at the first True branch. The check that protects you from a crash needs to come first. Which check is that?",
                ], earlier_sub[name], last={"question": f"Move the `{name} == \"\"` (empty-string) check *above* any line that uses `{name}[0]`.",
                                            "show_line": True,
                                            "fix_hint": "Check for the empty string first, then digits, then the first character."})
                return _finding("elif-order", 50, levels, earlier_sub[name], ref)
    return None


def detect_range_obo(lesson, tree, src):
    sol_tree, _ = _parse((lesson or {}).get("solution") or "")
    if not tree or not sol_tree:
        return None

    def ranges(t):
        out = []
        for n in ast.walk(t):
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == "range" and n.args:
                out.append((getattr(n, "lineno", None), [_dump(a) for a in n.args]))
        return out

    ur, sr = ranges(tree), ranges(sol_tree)
    if not ur or not sr:
        return None

    def has_plus1(args):
        return len(args) >= 2 and (args[1].endswith("+ 1") or args[1].endswith("+1"))

    if any(has_plus1(a) for _, a in sr) and not any(has_plus1(a) for _, a in ur):
        line = ur[0][0]
        levels, ref = _levels_from_note(lesson, "range-obo", [
            "`range` always stops *before* its second number (and a one-argument `range(n)` starts at 0 and stops before `n`). What is the last number you *need* the loop to visit?",
            "If you need to include `n` (or `total`) itself, the stop value has to be one more than that. What do you write for the stop?",
        ], line, last={"question": "This is the range that drives your loop. If it must reach `n` / `total`, the stop needs to be `n + 1` (or `total + 1`).",
                       "show_line": True,
                       "fix_hint": "Use `range(1, n + 1)` to visit 1, 2, \u2026, n. `range(n)` stops at n-1 and starts at 0."})
        return _finding("range-obo", 55, levels, line, ref)
    return None


def detect_indent(lesson, tree, src):
    sol_tree, _ = _parse((lesson or {}).get("solution") or "")
    if not tree or not sol_tree:
        return None

    def append_sites(t):
        in_if, in_loop, outside = [], [], []
        for s, loop, block, _fn in _walk_stmts(t):
            call = s.value if isinstance(s, ast.Expr) and isinstance(s.value, ast.Call) else None
            if call and _calls_named(call, {"append"}):
                if isinstance(block, ast.If):
                    in_if.append(s.lineno)
                elif isinstance(loop, (ast.For, ast.While)):
                    in_loop.append(s.lineno)
                else:
                    outside.append(s.lineno)
        return in_if, in_loop, outside

    sol_if, sol_loop, _ = append_sites(sol_tree)
    user_if, user_loop, user_out = append_sites(tree)
    if (sol_if or sol_loop) and user_out and not user_if and not user_loop:
        line = user_out[0]
    elif sol_if and user_loop and not user_if:
        line = user_loop[0]
    else:
        line = None
    if line:
        levels, ref = _levels_from_note(lesson, "indent", [
            "You call `.append(...)` in this program, but look at the spaces at the start of that line. Is it indented under the `for` or the `if`, or does it line up with them (so it runs *after* the loop)?",
            "A line that should happen once *per item* (or only when a condition is True) has to be indented *inside* that block. Which block should this append belong to?",
        ], line, last={"question": "This `.append(...)` is not indented under the loop or `if` that should control it. Indent it so it belongs to that block.",
                       "show_line": True,
                       "fix_hint": "Indent this line with 4 more spaces so it sits inside the `for` / `if`."})
        return _finding("indent", 60, levels, line, ref)
    return None


def detect_infinite_while(lesson, tree, src, run):
    if not tree:
        return None
    hits = []
    for s, _loop, _block, _fn in _walk_stmts(tree):
        if not isinstance(s, ast.While):
            continue
        body = ast.Module(body=s.body, type_ignores=[])
        body_has_break = any(isinstance(n, ast.Break) for n in ast.walk(body))
        names = {n.id for n in ast.walk(s.test) if isinstance(n, ast.Name)}
        assigned = set()
        for n in ast.walk(body):
            if isinstance(n, ast.Assign):
                for t in n.targets:
                    if isinstance(t, ast.Name):
                        assigned.add(t.id)
            if isinstance(n, ast.AugAssign) and isinstance(n.target, ast.Name):
                assigned.add(n.target.id)
        if isinstance(s.test, ast.Constant) and s.test.value is True and not body_has_break:
            hits.append(s.lineno)
        elif names and not (names & assigned) and not body_has_break:
            hits.append(s.lineno)
    if run and run.get("timeout") and not hits:
        for s, _loop, _block, _fn in _walk_stmts(tree):
            if isinstance(s, ast.While):
                hits.append(s.lineno)
                break
    if not hits:
        return None
    line = hits[0]
    levels, ref = _levels_from_note(lesson, "infinite-while", [
        "A `while` loop keeps going as long as its condition is True. What inside the body makes that condition change \u2014 or what `break` can stop it?",
        "If the variables in the condition never change, the loop never ends (and the app has to stop it). Which variable should be updated each time around?",
    ], line, last={"question": "This is the `while` that may never end. Make sure the body updates the condition (or `break`s when the task says to stop).",
                   "show_line": True})
    return _finding("infinite-while", 58, levels, line, ref)

def detect_names(lesson, tree, src, run):
    if not tree:
        return None
    if run and run.get("exc") == "NameError":
        m = re.search(r"name '(\w+)' is not defined", run.get("stderr") or "")
        name = m.group(1) if m else "this name"
        line = None
        gm = re.search(r'File "<tutor>", line (\d+)', run.get("tb") or "") or re.search(r'File "your_code\.py", line (\d+)', run.get("tb") or "")
        if gm:
            line = int(gm.group(1))
        if line is None:
            for n in ast.walk(tree):
                if isinstance(n, ast.Name) and n.id == name and isinstance(n.ctx, ast.Load):
                    line = n.lineno
                    break
        expl = explain_error(f"File \"your_code.py\", line {line or 1}\nNameError: name '{name}' is not defined\n", False, 10)
        levels, ref = _levels_from_note(lesson, "unassigned", [
            f"Python does not know `{name}`. Have you created it with a single `=` before this line, and is the spelling (and capitalisation) exactly the same?",
            expl or f"If `{name}` is only set inside an `if`, is there a path that skips that branch?",
        ], line, last={"question": f"This is the line that uses `{name}` before it has a value (or misspells it). Create `{name}` first, or fix the spelling.",
                       "show_line": True})
        return _finding("unassigned", 28, levels, line, ref)
    starter_tree, _ = _parse((lesson or {}).get("starter") or "")
    given = set()
    if starter_tree:
        for s, _loop, _block, _fn in _walk_stmts(starter_tree):
            if isinstance(s, ast.Assign):
                for t in s.targets:
                    if isinstance(t, ast.Name):
                        given.add(t.id)
    stored, loaded, skip_fn = {}, set(), set()
    for n in ast.walk(tree):
        if isinstance(n, ast.FunctionDef):
            skip_fn.add(n.name)
        if isinstance(n, ast.Name):
            if isinstance(n.ctx, ast.Store):
                stored.setdefault(n.id, n.lineno)
            else:
                loaded.add(n.id)
    unused = [name for name, ln in stored.items()
              if name not in loaded and name not in given and name not in skip_fn
              and not name.startswith("_") and name not in {"self", "i", "j", "k"}]
    if unused:
        name, line = unused[0], stored[unused[0]]
        levels, ref = _levels_from_note(lesson, "unused", [
            f"You give `{name}` a value, but nothing later uses it. Was it meant to be printed, returned, or added to a list \u2014 or is the name spelled differently later on?",
        ], line, last={"question": f"`{name}` is stored here and then never read. If the task asked you to print or return it, that line is still missing.",
                       "show_line": True})
        return _finding("unused", 85, levels, line, ref)
    return None


def detect_str_int(lesson, tree, src, run):
    hits = []
    if tree:
        for n in ast.walk(tree):
            if isinstance(n, ast.BinOp) and isinstance(n.op, ast.Add):
                L, R = _const(n.left), _const(n.right)
                types = set()
                if isinstance(n.left, ast.Constant):
                    types.add(type(L))
                if isinstance(n.right, ast.Constant):
                    types.add(type(R))
                if str in types and (int in types or float in types):
                    hits.append(n.lineno)
    stderr = (run or {}).get("stderr") or ""
    mix = "can only concatenate str" in stderr or ("unsupported operand type(s) for +" in stderr and "str" in stderr)
    if mix and not hits:
        hits.append(None)
    if not hits:
        return None
    line = hits[0]
    expl = explain_error(stderr, False, 10) if stderr else ""
    levels, ref = _levels_from_note(lesson, "str-int", [
        "You are combining text and a number with `+`. Python will not add those two kinds of value. Would `str(...)` or an f-string like `f\"total: {total}\"` do what you meant?",
        expl or "Check which side is text and which side is a number.",
    ], line, last={"question": "This is the line that mixes text and a number. Use an f-string, or convert the number with `str(...)`.",
                   "show_line": True,
                   "fix_hint": "Write `f\"... {value}\"` or `\"...\" + str(value)` \u2014 do not `+` a string and an int directly."})
    return _finding("str-int", 65, levels, line, ref)


def detect_hardcode(lesson, tree, src, run, sol_run):
    if not tree:
        return None
    sol_out = (sol_run or {}).get("stdout") or ""
    sol_lines = [ln for ln in sol_out.splitlines() if ln.strip()]
    sol_tree, _ = _parse((lesson or {}).get("solution") or "")
    hits = []
    sol_consts = []
    if sol_tree:
        for sn in ast.walk(sol_tree):
            if isinstance(sn, ast.Call) and isinstance(sn.func, ast.Name) and sn.func.id == "print":
                sol_consts += [_const(x) for x in sn.args]
    for n in ast.walk(tree):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == "print":
            for a in n.args:
                v = _const(a)
                if isinstance(v, (int, float)) and any(re.fullmatch(r"-?\d+(\.\d+)?", ln) and str(v) == ln for ln in sol_lines):
                    if v not in sol_consts:
                        hits.append((n.lineno, v))
                if isinstance(v, str) and v in sol_lines and v not in ((lesson or {}).get("starter") or ""):
                    uses_vars = False
                    if sol_tree:
                        for sn in ast.walk(sol_tree):
                            if isinstance(sn, ast.Call) and isinstance(sn.func, ast.Name) and sn.func.id == "print":
                                if any(isinstance(x, (ast.JoinedStr, ast.Name, ast.BinOp, ast.Call)) for x in sn.args):
                                    uses_vars = True
                    if uses_vars:
                        hits.append((n.lineno, v))
        # also: name = <expected number>; print(name)
        if isinstance(n, ast.Assign) and len(n.targets) == 1 and isinstance(n.targets[0], ast.Name):
            v = _const(n.value)
            if isinstance(v, (int, float)) and any(re.fullmatch(r"-?\d+(\.\d+)?", ln) and str(v) == ln for ln in sol_lines):
                if v not in sol_consts:
                    printed = False
                    for call in ast.walk(tree):
                        if isinstance(call, ast.Call) and isinstance(call.func, ast.Name) and call.func.id == "print":
                            for a in call.args:
                                if isinstance(a, ast.Name) and a.id == n.targets[0].id:
                                    printed = True
                                if isinstance(a, ast.JoinedStr):
                                    for fv in a.values:
                                        if isinstance(fv, ast.FormattedValue) and isinstance(fv.value, ast.Name) and fv.value.id == n.targets[0].id:
                                            printed = True
                    if printed:
                        hits.append((n.lineno, v))
        if isinstance(n, ast.Assign) and isinstance(n.value, ast.List) and n.value.elts and all(
                isinstance(_const(e), (int, str)) for e in n.value.elts):
            lit = [_const(e) for e in n.value.elts]
            for val in ((sol_run or {}).get("names") or {}).values():
                if val == lit and len(lit) >= 2:
                    sol_has_lit = False
                    if sol_tree:
                        for sn in ast.walk(sol_tree):
                            if isinstance(sn, ast.List) and [_const(e) for e in sn.elts] == lit:
                                sol_has_lit = True
                    if not sol_has_lit:
                        hits.append((n.lineno, lit))
                        break
    if not hits:
        return None
    line = hits[0][0]
    levels, ref = _levels_from_note(lesson, "hardcode", [
        "The checker will try *other* inputs, not just the example in the task. Did you type a finished answer, or did you write steps that still work when the inputs change?",
        "If the task changed a number or a word, which part of your code would have to change? If the answer is \"the printed value itself\", you are probably hard-coding it.",
    ], line, last={"question": "This line writes a finished value instead of computing it from the variables the task gave you. Use those variables (and a loop or an f-string) so other inputs still work.",
                   "show_line": True})
    return _finding("hardcode", 70, levels, line, ref)


def detect_output_format(lesson, tree, src, run, sol_run):
    sol_tree, _ = _parse((lesson or {}).get("solution") or "")
    diffs = []
    if tree and sol_tree:
        u, s = _print_shapes(tree), _print_shapes(sol_tree)
        if u and s:
            up, sp = "".join(u[0][1]), "".join(s[0][1])
            if up and sp and up != sp:
                d = char_diff(up, sp)
                if not d["same"]:
                    diffs.append((u[0][0], d, "source"))
    if run and run.get("ok") and sol_run and sol_run.get("ok"):
        got, want = run.get("stdout") or "", sol_run.get("stdout") or ""
        if got != want and want.strip():
            gl, wl = got.splitlines(), want.splitlines()
            for i in range(max(len(gl), len(wl))):
                a = gl[i] if i < len(gl) else ""
                b = wl[i] if i < len(wl) else ""
                if a != b:
                    d = char_diff(a, b)
                    letters = lambda s: re.sub(r"\s+", "", s).lower()
                    if letters(a) == letters(b) or d["kind"] in {"extra-space", "missing-space", "case", "punct", "extra", "missing"}:
                        diffs.append((None, d, "stdout"))
                    break
    snippets = _expected_snippets(lesson)
    if tree and snippets:
        for ln, parts, _dump_ in _print_shapes(tree):
            shape = "".join(parts)
            for snip in snippets:
                for token in re.findall(r"\s*->\s*|\s*/\s*|\s*:\s*", snip):
                    if token in snip and token not in shape and any(ch in shape for ch in token.strip()):
                        loose = re.search(r"\s*" + re.escape(token.strip()) + r"\s*", shape)
                        if loose and loose.group(0) != token:
                            diffs.append((ln, char_diff(loose.group(0), token), "source"))
    if not diffs:
        return None
    line, d, how = diffs[0]
    for ln, dd, h in diffs:
        if ln:
            line, d, how = ln, dd, h
            break
    pretty = _fmt_diff(d)
    levels, ref = _levels_from_note(lesson, "output-format", [
        "Your program runs, but the printed text is not *exactly* what the task asked for. Have you compared the two character by character \u2014 spaces, punctuation and capitals?",
        "One extra or missing space is enough for the checker to say no. Look at the mark in the comparison below: what is different?",
    ], line, last={"question": "This is the print line to fix. Adjust the spaces, punctuation or capitals so it matches the task exactly.",
                   "show_line": True,
                   "fix_hint": "Compare the task's example output with yours character by character, then edit this print or f-string."})
    if pretty and levels:
        levels[min(1, len(levels) - 1)]["note"] = pretty
        if levels[-1].get("show_line"):
            levels[-1]["note"] = pretty
    if d.get("want") and not _note_for(lesson, "output-format").get("task_ref"):
        ref = (d["want"][:40] or ref)
    return _finding("output-format", 75, levels, line, ref or _task_focus(lesson), diff=d)


def detect_runtime(lesson, src, run):
    if not run or run.get("ok") or run.get("syntax") or run.get("timeout"):
        return None
    if run.get("exc") in {None, "NameError"}:
        if not run.get("stderr") or run.get("exc") == "NameError":
            return None
    blob = (run.get("stderr") or "")
    if "your_code.py" not in (run.get("tb") or ""):
        blob = f"File \"your_code.py\", line 1\n{blob}"
    expl = explain_error(blob, False, 10)
    line = None
    blob = (run.get("tb") or "") + "\n" + (run.get("stderr") or "")
    m = re.search(r'File "<tutor>", line (\d+)', blob) or re.search(r'File "your_code\.py", line (\d+)', blob)
    if m:
        line = int(m.group(1))
    levels, ref = _levels_from_note(lesson, "runtime", [
        expl or "Python stopped with an error. Read the last line of the error: it names the problem. What is it asking you to look at?",
        "Fix this error first, then run again. The checker cannot judge the result until the program finishes.",
    ], line, last={"question": "This is the line the error points at (sometimes the mistake is on the line just above). What will you change?",
                   "show_line": True})
    return _finding("runtime", 80, levels, line, ref)

