def _call_det(fn, lesson, tree, src, run, sol_run):
    try:
        names = fn.__code__.co_varnames[: fn.__code__.co_argcount]
        kw = {"lesson": lesson, "tree": tree, "src": src, "run": run, "sol_run": sol_run}
        return fn(**{k: kw[k] for k in names if k in kw})
    except Exception:
        return None


def findings(lesson, code, check=None):
    """Return a priority-sorted list of finding dicts for this code."""
    src = code or ""
    tree, err = _parse(src)
    run = sol_run = None
    if _safe_to_exec(lesson, src):
        if tree is not None:
            run = _exec(src)
        sol = (lesson or {}).get("solution") or ""
        if sol and _safe_to_exec(lesson, sol):
            sol_run = _exec(sol)
    out = []
    if err:
        f = detect_syntax(lesson, src, err)
        if f:
            out.append(f)
        return out
    for fn in DETECTORS:
        f = _call_det(fn, lesson, tree, src, run, sol_run)
        if f:
            out.append(f)
    out.sort(key=lambda f: (f["priority"], f.get("line") or 0))
    return out


def _read_nudge(lesson, finding):
    ref = (finding or {}).get("task_ref") or _task_focus(lesson) or ""
    phrase = ref.strip().strip("`")
    if not phrase:
        return "Look back at the task. Compare what it asked for with your code, line by line and character by character."
    return (f"Look back at the task line about \u201c{_clip(phrase, 50)}\u201d. "
            "Point at that line, then compare it with your code character by character.")


def advise(lesson, code, check=None, finding=0, level=0):
    """One Socratic nudge. `finding` and `level` are 0-based; Next nudge increments level, then finding."""
    found = findings(lesson, code, check)
    if not found:
        passed = bool(check and check.get("status") == "pass")
        q = ("Your code looks like it is doing the job. Try Check if you have not already. "
             "If the checker still disagrees, compare its message with the task character by character.")
        if passed:
            q = "The checker already accepted this code. If you want a walkthrough, pick a line and use Explain this line, or Trace it to see the variables change."
        return {"ok": True, "empty": True, "more": False, "rule": "", "finding_i": 0, "finding_n": 0,
                "level": 0, "level_n": 0, "question": q, "note": "", "line": None, "line_text": "",
                "fix_hint": "", "diff": None, "task_ref": _task_focus(lesson) or "",
                "read": _read_nudge(lesson, {"task_ref": _task_focus(lesson)}), "passed": passed,
                "rules": [], "show_line": False}
    i = max(0, min(int(finding or 0), len(found) - 1))
    f = found[i]
    levels = f["levels"]
    lv = max(0, min(int(level or 0), len(levels) - 1))
    cur = levels[lv]
    last = lv == len(levels) - 1
    more = (lv < len(levels) - 1) or (i < len(found) - 1)
    line = f.get("line")
    line_text = _at(code or "", line) if last and cur.get("show_line") and line else ""
    fix = cur.get("fix_hint") if last else ""
    sol = ((lesson or {}).get("solution") or "").strip()

    def scrub(s):
        if sol and s and sol in s:
            return s.replace(sol, "the intended program")
        return s

    note = cur.get("note") or ""
    if f.get("diff") and not f["diff"].get("same") and not note:
        note = _fmt_diff(f["diff"])
    show = bool(last and cur.get("show_line"))
    return {
        "ok": True, "empty": False, "more": more, "rule": f["rule"],
        "finding_i": i, "finding_n": len(found),
        "level": lv, "level_n": len(levels),
        "question": scrub(cur["question"]), "note": scrub(note),
        "line": line if show or lv > 0 else line,
        "line_text": line_text, "fix_hint": scrub(fix),
        "diff": f.get("diff"), "task_ref": f.get("task_ref") or "",
        "read": _read_nudge(lesson, f), "passed": False,
        "rules": [x["rule"] for x in found],
        "show_line": show,
    }


def _preview(v, n=40):
    try:
        if isinstance(v, (int, float, bool, type(None))):
            return repr(v)
        if isinstance(v, str):
            return repr(v if len(v) <= n else v[:n] + "\u2026")
        if isinstance(v, list):
            if len(v) <= 8:
                return "[" + ", ".join(_preview(x, 16) for x in v) + "]"
            return f"list(len={len(v)})"
        if isinstance(v, tuple):
            if len(v) <= 8:
                return "(" + ", ".join(_preview(x, 16) for x in v) + ")"
            return f"tuple(len={len(v)})"
        if isinstance(v, dict):
            return f"dict(len={len(v)})"
        return _clip(repr(v), n)
    except Exception:
        return "\u2026"


def _too_big_to_trace(lesson, src):
    if not _safe_to_exec(lesson, src):
        return "This program is too big (or too slow) to trace step by step. Trace works best on short practice programs."
    if len(_lines(src or "")) > MAX_TRACE_LINES:
        return f"This file has more than {MAX_TRACE_LINES} lines. Shrink it, or trace a tiny example of the same idea."
    return ""


def trace(code, lesson=None, max_steps=MAX_TRACE_STEPS, timeout=MAX_TRACE_SECS):
    src = code or ""
    reason = _too_big_to_trace(lesson, src)
    if reason:
        return {"ok": False, "steps": [], "stopped": "too-big", "reason": reason}
    tree, err = _parse(src)
    if err:
        return {"ok": False, "steps": [], "stopped": "syntax",
                "reason": "Python could not parse this file, so there is nothing to trace yet. Ask the tutor about the error, or fix the grammar first.",
                "line": err.lineno}
    steps, prev, t0, stopped = [], {}, time.time(), ""
    fnames = {"<trace>"}
    reason = ""
    pending = None  # line event fires BEFORE the line runs, so we record a line once the next one starts

    def snapshot(frame):
        cur = {k: v for k, v in frame.f_locals.items() if not k.startswith("_")}
        changed = {}
        for k, v in cur.items():
            if k not in prev or prev.get(k) != v:
                changed[k] = {"from": None if k not in prev else _preview(prev[k]), "to": _preview(v)}
        for k in list(prev):
            if k not in cur:
                changed[k] = {"from": _preview(prev[k]), "to": "(gone)"}
        prev.clear()
        prev.update(cur)
        return changed

    def flush(frame):
        nonlocal pending
        if not pending:
            return
        if len(steps) >= max_steps:
            raise TimeoutError("trace cap")
        pending["changed"] = snapshot(frame)
        pending["n"] = len(steps) + 1
        steps.append(pending)
        pending = None

    def tracer(frame, event, arg):
        nonlocal stopped, pending
        if frame.f_code.co_filename not in fnames:
            return None
        if time.time() - t0 > timeout:
            stopped = "timeout"
            raise TimeoutError("trace cap")
        if event == "line":
            try:
                flush(frame)
            except TimeoutError:
                stopped = "cap"
                raise
            pending = {"line": frame.f_lineno, "text": _at(src, frame.f_lineno), "changed": {}}
        return tracer

    ns = {"__name__": "__main__"}
    try:
        sys.settrace(tracer)
        with redirect_stdout(io.StringIO()):
            exec(compile(tree, "<trace>", "exec"), ns)
    except TimeoutError:
        pass
    except BaseException as e:  # noqa
        if not stopped:
            stopped = "error"
            reason = explain_error(
                f"File \"your_code.py\", line {getattr(e, 'lineno', 0) or 1}\n"
                + "".join(traceback.format_exception_only(type(e), e)), False, 10)
    finally:
        sys.settrace(None)
        if pending is not None and stopped not in {"cap", "timeout"}:
            class _F:
                f_locals = {k: v for k, v in ns.items() if not k.startswith("_")}
            try:
                pending["changed"] = snapshot(_F())
            except Exception:
                pending["changed"] = pending.get("changed") or {}
            pending["n"] = len(steps) + 1
            steps.append(pending)
            pending = None
    if stopped == "cap":
        reason = f"Stopped after {max_steps} steps so the trace stays readable. The program may have more to do."
    elif stopped == "timeout":
        reason = f"Stopped after {timeout:.0f} seconds. A loop may not be ending \u2014 ask the tutor about it."
    return {"ok": True, "steps": steps, "stopped": stopped, "reason": reason or "", "n": len(steps)}


def handle(lesson, payload):
    """JSON-friendly entry used by /api/tutor and the Pyodide runner."""
    action = (payload or {}).get("action") or "advise"
    code = (payload or {}).get("code") or ""
    check = (payload or {}).get("check")
    if action == "explain":
        return explain_line(code, payload.get("line"), lesson)
    if action == "trace":
        return trace(code, lesson)
    return advise(lesson, code, check=check,
                  finding=payload.get("finding") or 0,
                  level=payload.get("level") or 0)

